def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    # Find the multicolored template as the largest connected component of
    # non-background cells, using 8-way connectivity.
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    comps = []
    while cells:
        seed = cells.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in cells:
                        cells.remove(p)
                        comp.add(p)
                        stack.append(p)
        comps.append(comp)

    template = max(comps, key=len)
    r0 = min(r for r, c in template)
    r1 = max(r for r, c in template)
    c0 = min(c for r, c in template)
    c1 = max(c for r, c in template)
    shape = [[grid[r][c] for c in range(c0, c1 + 1)]
             for r in range(r0, r1 + 1)]

    targets = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in template]
    out = [row[:] for row in grid]
    for tr, tc in targets:
        top = tr - len(shape) // 2
        left = tc - len(shape[0]) // 2
        for i in range(len(shape)):
            for j in range(len(shape[0])):
                if shape[i][j] != bg:
                    rr, cc = top + i, left + j
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = shape[i][j]
    return out
